{
  "hypotheses": [
    {
      "text": "IBM's sic_code in edgar.company_profiles is stored as an integer without leading zeros, while the reference sic_codes_table stores codes as strings with leading zeros (e.g., '0371' vs 371), causing the join to fail.",
      "how_to_test": "SELECT cp.cik, cp.entity_name, cp.sic_code, cs.sic_code AS ref_sic FROM edgar.company_profiles cp LEFT JOIN company_dns.sic_codes_table cs ON cp.sic_code = cs.sic_code WHERE cp.cik = 51143 AND cs.sic_code IS NULL;\n-- Then test if padding helps: SELECT cp.cik, cp.entity_name, lp.sic_code AS padded FROM edgar.company_profiles cp LEFT JOIN company_dns.sic_codes_table lp ON LPAD(cp.sic_code, 4, '0') = lp.sic_code WHERE cp.cik = 51143;"
    },
    {
      "text": "IBM's sic_code field in edgar.company_profiles is NULL or empty for some filings (perhaps due to missing XBRL tagging), so there is no value to match against the reference table.",
      "how_to_test": "SELECT COUNT(*) AS total_rows, SUM(CASE WHEN sic_code IS NULL OR TRIM(sic_code) = '' THEN 1 ELSE 0 END) AS missing_sic FROM edgar.company_profiles WHERE cik = 51143;"
    },
    {
      "text": "IBM reports its primary industry using NAICS classification rather than SIC, and the sic_code column in edgar.company_profiles actually contains a NAICS code (e.g., 541511) that does not exist in the SIC reference list, causing the join to drop IBM.",
      "how_to_test": "SELECT DISTINCT cp.sic_code FROM edgar.company_profiles cp WHERE cp.cik = 51143 LIMIT 10;\n-- Check if any of those codes appear in the NAICS reference (if available) or fall outside typical SIC range (0000-9999): SELECT sic_code FROM edgar.company_profiles WHERE cik = 51143 AND (sic_code < '0000'::text OR sic_code > '9999'::text);"
    },
    {
      "text": "The company_dns.sic_codes_table is missing certain SIC codes due to an outdated version of the reference dataset (e.g., it excludes newer or reassigned SIC codes that IBM now uses after divestitures such as Kyndryl).",
      "how_to_test": "SELECT cp.sic_code FROM edgar.company_profiles cp WHERE cp.cik = 51143 EXCEPT SELECT sic_code FROM company_dns.sic_codes_table;\n-- If any codes are returned, they are absent from the reference table, indicating a coverage gap."
    }
  ]
}
